<?php
declare(strict_types=1);
namespace App\Models\Repositories;
use PDO;
final class CampaignRepository { public function __construct(private PDO $db){}
 public function list(int $u):array{$s=$this->db->prepare('SELECT c.*,COUNT(r.id) recipients,SUM(r.status="sent") sent FROM campaigns c LEFT JOIN campaign_recipients r ON r.campaign_id=c.id WHERE c.user_id=:u GROUP BY c.id ORDER BY c.id DESC');$s->execute(['u'=>$u]);return$s->fetchAll();}
 public function create(int $u,array $d):int{$s=$this->db->prepare('INSERT INTO campaigns(user_id,title,subject,body_html,body_text,social_links) VALUES(:u,:title,:subject,:html,:text,:links)');$s->execute(['u'=>$u,'title'=>$d['title'],'subject'=>$d['subject'],'html'=>$d['body'],'text'=>strip_tags($d['body']),'links'=>json_encode($d['links'])]);return(int)$this->db->lastInsertId();}
 public function finalize(int $id,int $u,int $limit):void{$this->db->beginTransaction();try{$s=$this->db->prepare("SELECT id,email,name FROM contacts WHERE user_id=:u AND status='active' AND NOT EXISTS(SELECT 1 FROM global_suppression_list g WHERE g.email_hash=SHA2(contacts.email,256))");$s->execute(['u'=>$u]);$contacts=$s->fetchAll();$plan=(new \App\Services\BatchPlanner())->plan(count($contacts),$limit);$batch=$this->db->prepare('INSERT INTO campaign_batches(campaign_id,sequence_number,scheduled_at) VALUES(:c,:seq,:at)');$recipient=$this->db->prepare('INSERT INTO campaign_recipients(campaign_id,batch_id,contact_id,email,recipient_name) VALUES(:c,:b,:contact,:email,:name)');$offset=0;foreach($plan as $seq=>$p){$batch->execute(['c'=>$id,'seq'=>$seq+1,'at'=>$p['scheduled_at']]);$bid=(int)$this->db->lastInsertId();for($i=0;$i<$p['size'];$i++){$x=$contacts[$offset++];$recipient->execute(['c'=>$id,'b'=>$bid,'contact'=>$x['id'],'email'=>$x['email'],'name'=>$x['name']]);}}$q=$this->db->prepare("UPDATE campaigns SET status='queued',finalized_at=NOW() WHERE id=:id AND user_id=:u AND status='draft'");$q->execute(['id'=>$id,'u'=>$u]);$this->db->commit();}catch(\Throwable $e){$this->db->rollBack();throw$e;}}
 public function setStatus(int $id,int $u,string $status):void{$s=$this->db->prepare('UPDATE campaigns SET status=:s,paused_at=IF(:s="paused",NOW(),NULL) WHERE id=:id AND user_id=:u');$s->execute(['s'=>$status,'id'=>$id,'u'=>$u]);}
 public function dashboard(int $id,int $u):array{$s=$this->db->prepare("SELECT c.status,COUNT(r.id) total,SUM(r.status='sent') sent,SUM(r.status='failed') failed,SUM(r.status='pending') pending FROM campaigns c LEFT JOIN campaign_recipients r ON r.campaign_id=c.id WHERE c.id=:id AND c.user_id=:u GROUP BY c.id");$s->execute(['id'=>$id,'u'=>$u]);return$s->fetch()?:[];}
 public function hourlyLimit(int $user):int{$s=$this->db->prepare('SELECT hourly_limit FROM sender_settings WHERE user_id=:u');$s->execute(['u'=>$user]);return max(1,min(200,(int)($s->fetchColumn()?:30)));}
}
